Set-StrictMode -Version 2.0
$ErrorActionPreference = 'Stop'

function Test-PathBool {
    param([string]$Path)
    if ([string]::IsNullOrWhiteSpace($Path)) { return $false }
    return [bool](Test-Path -LiteralPath $Path -ErrorAction SilentlyContinue)
}

function ConvertTo-ShortCommand {
    param([string]$CommandLine, [int]$Max = 180)
    if ([string]::IsNullOrWhiteSpace($CommandLine)) { return '' }
    $oneLine = ($CommandLine -replace '\s+', ' ').Trim()
    if ($oneLine.Length -le $Max) { return $oneLine }
    return $oneLine.Substring(0, $Max - 3) + '...'
}

function Get-ChildDirsSafe {
    param([string]$Path, [int]$Depth = 4)
    if (-not (Test-PathBool $Path)) { return @() }
    try {
        return @(Get-ChildItem -LiteralPath $Path -Directory -Recurse -Depth $Depth -ErrorAction SilentlyContinue)
    }
    catch {
        return @()
    }
}

function Get-CandidatePaths {
    param([string]$BaseRoot)

    $explicitComfyRoots = @(
        $BaseRoot,
        (Join-Path $BaseRoot 'ComfyUI'),
        (Join-Path $BaseRoot 'ComfyUI-Easy-Install\ComfyUI'),
        (Join-Path $BaseRoot 'ComfyUI_windows_portable\ComfyUI'),
        (Join-Path $BaseRoot 'ComfyUI-Easy-Install\ComfyUI_windows_portable\ComfyUI')
    )

    $recursiveComfyRoots = Get-ChildDirsSafe -Path $BaseRoot -Depth 5 |
        Where-Object { $_.Name -eq 'ComfyUI' } |
        Select-Object -ExpandProperty FullName

    $comfyRoots = @($explicitComfyRoots + $recursiveComfyRoots) |
        Where-Object { $_ -and (Test-PathBool (Join-Path $_ 'main.py')) } |
        Select-Object -Unique

    $explicitPython = @(
        (Join-Path $BaseRoot 'python_embeded\python.exe'),
        (Join-Path $BaseRoot 'ComfyUI-Easy-Install\python_embeded\python.exe'),
        (Join-Path $BaseRoot 'ComfyUI_windows_portable\python_embeded\python.exe'),
        (Join-Path $BaseRoot 'ComfyUI-Easy-Install\ComfyUI_windows_portable\python_embeded\python.exe')
    )

    $recursivePython = Get-ChildDirsSafe -Path $BaseRoot -Depth 5 |
        Where-Object { $_.FullName -match 'python_embeded$' } |
        ForEach-Object { Join-Path $_.FullName 'python.exe' }

    $pythonPaths = @($explicitPython + $recursivePython) |
        Where-Object { $_ -and (Test-PathBool $_) } |
        Select-Object -Unique

    return [pscustomobject]@{
        rootExists = Test-PathBool $BaseRoot
        root = $BaseRoot
        comfyRoots = @($comfyRoots)
        embeddedPythons = @($pythonPaths)
    }
}

function Get-InterestingProcesses {
    param([string]$BaseRoot)

    try {
        $items = Get-CimInstance Win32_Process -ErrorAction Stop | Where-Object {
            $_.ProcessId -ne $PID -and
            $_.CommandLine -and
            (
                $_.CommandLine -like "*$BaseRoot*" -or
                $_.CommandLine -like '*ComfyUI_Easy_Install*' -or
                $_.CommandLine -like '*ComfyUI-Easy-Install*' -or
                $_.CommandLine -like '*python_embeded*' -or
                $_.CommandLine -like '*torch==2.9.1*' -or
                $_.CommandLine -like '*uv pip*'
            )
        }

        return @($items | Sort-Object ProcessId | ForEach-Object {
            [pscustomobject]@{
                processId = $_.ProcessId
                parentProcessId = $_.ParentProcessId
                name = $_.Name
                executablePath = $_.ExecutablePath
                command = ConvertTo-ShortCommand $_.CommandLine
                isTorchPip = [bool]($_.CommandLine -match 'torch==2\.9\.1|torchvision==0\.24\.1|torchaudio==2\.9\.1')
                isEasyInstall = [bool]($_.CommandLine -match 'ComfyUI-Easy-Install|ComfyUI_Easy_Install')
            }
        })
    }
    catch {
        return @([pscustomobject]@{ error = $_.Exception.Message })
    }
}

function Get-PortStatus {
    param([int[]]$PortList)

    $results = foreach ($port in $PortList) {
        $listeners = @()
        try {
            $listeners = @(Get-NetTCPConnection -LocalPort $port -State Listen -ErrorAction SilentlyContinue)
        }
        catch {
            $listeners = @()
        }

        if ($listeners.Count -eq 0) {
            [pscustomobject]@{
                port = $port
                listening = $false
                owningProcess = $null
                processName = $null
                localAddress = $null
            }
            continue
        }

        foreach ($listener in $listeners) {
            $proc = $null
            try { $proc = Get-Process -Id $listener.OwningProcess -ErrorAction SilentlyContinue } catch {}
            [pscustomobject]@{
                port = $port
                listening = $true
                owningProcess = $listener.OwningProcess
                processName = if ($proc) { $proc.ProcessName } else { $null }
                localAddress = $listener.LocalAddress
            }
        }
    }

    return @($results)
}

function Get-LatestLogs {
    param([string]$BaseRoot)

    $logRoots = @(
        (Join-Path $BaseRoot 'logs'),
        (Join-Path $BaseRoot 'ComfyUI-Easy-Install\logs')
    ) | Where-Object { Test-PathBool $_ } | Select-Object -Unique

    $logs = foreach ($logRoot in $logRoots) {
        Get-ChildItem -LiteralPath $logRoot -File -ErrorAction SilentlyContinue |
            Where-Object { $_.Extension -in @('.log', '.txt') } |
            Sort-Object LastWriteTime -Descending |
            Select-Object -First 8
    }

    return @($logs | Sort-Object LastWriteTime -Descending | Select-Object -First 8 | ForEach-Object {
        $tail = @()
        try { $tail = @(Get-Content -LiteralPath $_.FullName -Tail 6 -ErrorAction SilentlyContinue) } catch {}
        [pscustomobject]@{
            path = $_.FullName
            lastWriteTime = $_.LastWriteTime.ToString('s')
            sizeBytes = $_.Length
            tail = @($tail)
        }
    })
}

function Invoke-JsonGet {
    param([string]$Url, [int]$Timeout = 4)

    try {
        $response = Invoke-RestMethod -Uri $Url -Method Get -TimeoutSec $Timeout -ErrorAction Stop
        return [pscustomobject]@{
            ok = $true
            url = $Url
            error = $null
            data = $response
        }
    }
    catch {
        return [pscustomobject]@{
            ok = $false
            url = $Url
            error = $_.Exception.Message
            data = $null
        }
    }
}

function Invoke-ProcessCapture {
    param(
        [string]$FilePath,
        [string[]]$Arguments,
        [int]$Timeout = 8
    )

    if (-not (Test-PathBool $FilePath)) {
        return [pscustomobject]@{
            ok = $false
            exitCode = $null
            timedOut = $false
            stdout = ''
            stderr = "File not found: $FilePath"
        }
    }

    $stdout = [System.IO.Path]::GetTempFileName()
    $stderr = [System.IO.Path]::GetTempFileName()
    $process = $null

    try {
        $psi = [System.Diagnostics.ProcessStartInfo]::new()
        $psi.FileName = $FilePath
        $psi.UseShellExecute = $false
        $psi.RedirectStandardOutput = $false
        $psi.RedirectStandardError = $false
        $psi.CreateNoWindow = $true

        foreach ($arg in $Arguments) {
            [void]$psi.ArgumentList.Add($arg)
        }

        $process = [System.Diagnostics.Process]::new()
        $process.StartInfo = $psi

        $process.Start() | Out-Null
        $exited = $process.WaitForExit($Timeout * 1000)
        if (-not $exited) {
            try { $process.Kill() } catch {}
            return [pscustomobject]@{
                ok = $false
                exitCode = $null
                timedOut = $true
                stdout = ''
                stderr = "Timed out after $Timeout seconds"
            }
        }

        return [pscustomobject]@{
            ok = ($process.ExitCode -eq 0)
            exitCode = $process.ExitCode
            timedOut = $false
            stdout = ''
            stderr = ''
        }
    }
    catch {
        return [pscustomobject]@{
            ok = $false
            exitCode = $null
            timedOut = $false
            stdout = ''
            stderr = $_.Exception.Message
        }
    }
    finally {
        foreach ($path in @($stdout, $stderr)) {
            try { Remove-Item -LiteralPath $path -Force -ErrorAction SilentlyContinue } catch {}
        }
        if ($process) { $process.Dispose() }
    }
}

function Invoke-PythonJson {
    param(
        [string]$Python,
        [string]$Code,
        [int]$Timeout = 8
    )

    if (-not (Test-PathBool $Python)) {
        return [pscustomobject]@{ ok = $false; error = "Python not found: $Python"; data = $null }
    }

    $job = Start-Job -ScriptBlock {
        param($File, $Snippet)
        $output = & $File -I -c $Snippet 2>&1 | Out-String
        [pscustomobject]@{
            exitCode = $LASTEXITCODE
            output = $output.Trim()
        }
    } -ArgumentList $Python, $Code

    try {
        $done = Wait-Job -Job $job -Timeout $Timeout
        if (-not $done) {
            Stop-Job -Job $job -ErrorAction SilentlyContinue | Out-Null
            return [pscustomobject]@{ ok = $false; error = "Timed out after $Timeout seconds"; data = $null }
        }

        $result = Receive-Job -Job $job
        if ($result.exitCode -ne 0) {
            return [pscustomobject]@{ ok = $false; error = $result.output; data = $null }
        }

        try {
            return [pscustomobject]@{ ok = $true; error = $null; data = ($result.output | ConvertFrom-Json) }
        }
        catch {
            return [pscustomobject]@{ ok = $false; error = "Non-JSON output: $($result.output)"; data = $null }
        }
    }
    finally {
        Remove-Job -Job $job -Force -ErrorAction SilentlyContinue | Out-Null
    }
}

function Get-StatusObject {
    param([string]$BaseRoot)

    $paths = Get-CandidatePaths -BaseRoot $BaseRoot
    [pscustomobject]@{
        generatedAt = (Get-Date).ToString('s')
        mode = 'read-only'
        root = $BaseRoot
        paths = $paths
        processes = @(Get-InterestingProcesses -BaseRoot $BaseRoot)
        ports = @(Get-PortStatus -PortList $Ports)
        logs = @(Get-LatestLogs -BaseRoot $BaseRoot)
    }
}

function Get-ModelChecks {
    param([string[]]$ComfyRoots)

    $relativePaths = @(
        'models\insightface\inswapper_128.onnx',
        'models\insightface\models\buffalo_l',
        'models\reswapper',
        'models\hyperswap',
        'models\facerestore_models',
        'models\ultralytics\bbox\face_yolov8m.pt',
        'models\sams'
    )

    foreach ($comfyRoot in $ComfyRoots) {
        foreach ($relative in $relativePaths) {
            $full = Join-Path $comfyRoot $relative
            [pscustomobject]@{
                comfyRoot = $comfyRoot
                relativePath = $relative
                exists = Test-PathBool $full
                path = $full
            }
        }
    }
}

function Get-VerifyObject {
    param([string]$BaseRoot)

    $paths = Get-CandidatePaths -BaseRoot $BaseRoot
    $python = @($paths.embeddedPythons | Select-Object -First 1)
    $comfyRoots = @($paths.comfyRoots)

    $torchCheck = $null
    if ($python.Count -gt 0) {
        $torchSnippet = @'
import json, sys
r = {"python": sys.executable}
try:
    import torch
    r["torch_import"] = True
    r["torch_version"] = getattr(torch, "__version__", None)
    r["cuda_available"] = bool(torch.cuda.is_available())
    r["cuda_version"] = getattr(torch.version, "cuda", None)
    r["device_count"] = int(torch.cuda.device_count()) if torch.cuda.is_available() else 0
except Exception as e:
    r["torch_import"] = False
    r["torch_error"] = repr(e)
print(json.dumps(r))
'@
        $torchCheck = Invoke-PythonJson -Python $python[0] -Code $torchSnippet -Timeout ([Math]::Max($TimeoutSec, 8))
    }
    else {
        $torchCheck = [pscustomobject]@{ ok = $false; error = 'No embedded Python found'; data = $null }
    }

    $apiChecks = foreach ($port in $Ports) {
        $base = "http://127.0.0.1:$port"
        $system = Invoke-JsonGet -Url "$base/system_stats" -Timeout $TimeoutSec
        $objectInfo = Invoke-JsonGet -Url "$base/object_info" -Timeout $TimeoutSec
        $reactorNodes = @()
        if ($objectInfo.ok -and $objectInfo.data) {
            $reactorNodes = @($objectInfo.data.PSObject.Properties.Name | Where-Object { $_ -match 'ReActor|FaceSwap|reactor' } | Sort-Object)
        }
        [pscustomobject]@{
            port = $port
            systemStatsOk = $system.ok
            systemStatsError = $system.error
            objectInfoOk = $objectInfo.ok
            objectInfoError = $objectInfo.error
            reactorNodes = @($reactorNodes)
        }
    }

    $reactorFolders = foreach ($comfyRoot in $comfyRoots) {
        $folder = Join-Path $comfyRoot 'custom_nodes\ComfyUI-ReActor'
        [pscustomobject]@{
            comfyRoot = $comfyRoot
            path = $folder
            exists = Test-PathBool $folder
            pyproject = Test-PathBool (Join-Path $folder 'pyproject.toml')
            init = Test-PathBool (Join-Path $folder '__init__.py')
        }
    }

    [pscustomobject]@{
        generatedAt = (Get-Date).ToString('s')
        mode = 'read-only'
        root = $BaseRoot
        paths = $paths
        selectedPython = if ($python.Count -gt 0) { $python[0] } else { $null }
        torch = $torchCheck
        api = @($apiChecks)
        reactorFolders = @($reactorFolders)
        models = @(Get-ModelChecks -ComfyRoots $comfyRoots)
    }
}

function Write-StatusHuman {
    param($Status)

    Write-Host "Comfy Install Controller status ($($Status.mode))"
    Write-Host "Generated: $($Status.generatedAt)"
    Write-Host "Root: $($Status.root)"
    Write-Host ""
    Write-Host "Paths:"
    Write-Host "  root exists: $($Status.paths.rootExists)"
    Write-Host "  ComfyUI roots: $(@($Status.paths.comfyRoots).Count)"
    foreach ($path in @($Status.paths.comfyRoots)) { Write-Host "    - $path" }
    Write-Host "  embedded Python: $(@($Status.paths.embeddedPythons).Count)"
    foreach ($path in @($Status.paths.embeddedPythons)) { Write-Host "    - $path" }
    Write-Host ""
    Write-Host "Processes:"
    if (@($Status.processes).Count -eq 0) {
        Write-Host "  none matched"
    }
    else {
        foreach ($proc in @($Status.processes)) {
            Write-Host "  [$($proc.processId)] $($proc.name) torchPip=$($proc.isTorchPip) easyInstall=$($proc.isEasyInstall)"
            Write-Host "    $($proc.command)"
        }
    }
    Write-Host ""
    Write-Host "Ports:"
    foreach ($port in @($Status.ports)) {
        Write-Host "  $($port.port): listening=$($port.listening) process=$($port.processName) pid=$($port.owningProcess) address=$($port.localAddress)"
    }
    Write-Host ""
    Write-Host "Latest logs:"
    if (@($Status.logs).Count -eq 0) {
        Write-Host "  none found"
    }
    else {
        foreach ($log in @($Status.logs)) {
            Write-Host "  - $($log.path) ($($log.sizeBytes) bytes, $($log.lastWriteTime))"
            foreach ($line in @($log.tail)) { Write-Host "      $line" }
        }
    }
}

function Write-PlanHuman {
    param($Plan)

    Write-Host "$($Plan.name)"
    Write-Host "Mode: $($Plan.defaultMode)"
    Write-Host "Updated: $($Plan.updatedAt)"
    Write-Host ""
    $index = 1
    foreach ($stage in @($Plan.stages)) {
        Write-Host "$index. $($stage.title) [$($stage.id)]"
        Write-Host "   goal: $($stage.goal)"
        Write-Host "   command: $($stage.controllerCommand)"
        Write-Host "   confirmation required: $($stage.requiresConfirmation)"
        $index++
    }
}

function Write-VerifyHuman {
    param($Verify)

    Write-Host "Comfy Install Controller verify-existing ($($Verify.mode))"
    Write-Host "Generated: $($Verify.generatedAt)"
    Write-Host "Root: $($Verify.root)"
    Write-Host ""
    Write-Host "Discovered:"
    Write-Host "  ComfyUI roots: $(@($Verify.paths.comfyRoots).Count)"
    foreach ($path in @($Verify.paths.comfyRoots)) { Write-Host "    - $path" }
    Write-Host "  embedded Python: $(@($Verify.paths.embeddedPythons).Count)"
    foreach ($path in @($Verify.paths.embeddedPythons)) { Write-Host "    - $path" }
    Write-Host ""
    Write-Host "Torch:"
    Write-Host "  ok: $($Verify.torch.ok)"
    if ($Verify.torch.data) {
        Write-Host "  python: $($Verify.torch.data.python)"
        Write-Host "  torch_import: $($Verify.torch.data.torch_import)"
        Write-Host "  torch_version: $($Verify.torch.data.torch_version)"
        Write-Host "  cuda_available: $($Verify.torch.data.cuda_available)"
        Write-Host "  cuda_version: $($Verify.torch.data.cuda_version)"
        Write-Host "  device_count: $($Verify.torch.data.device_count)"
        if ($Verify.torch.data.torch_error) { Write-Host "  torch_error: $($Verify.torch.data.torch_error)" }
    }
    elseif ($Verify.torch.error) {
        Write-Host "  error: $($Verify.torch.error)"
    }
    Write-Host ""
    Write-Host "API:"
    foreach ($api in @($Verify.api)) {
        Write-Host "  port $($api.port): system_stats=$($api.systemStatsOk) object_info=$($api.objectInfoOk) reactor_nodes=$(@($api.reactorNodes).Count)"
        foreach ($node in @($api.reactorNodes)) { Write-Host "    - $node" }
        if (-not $api.systemStatsOk -and $api.systemStatsError) { Write-Host "    system error: $($api.systemStatsError)" }
        if (-not $api.objectInfoOk -and $api.objectInfoError) { Write-Host "    object_info error: $($api.objectInfoError)" }
    }
    Write-Host ""
    Write-Host "ReActor folders:"
    if (@($Verify.reactorFolders).Count -eq 0) {
        Write-Host "  no ComfyUI roots found"
    }
    foreach ($folder in @($Verify.reactorFolders)) {
        Write-Host "  exists=$($folder.exists) pyproject=$($folder.pyproject) init=$($folder.init) path=$($folder.path)"
    }
    Write-Host ""
    Write-Host "Models:"
    if (@($Verify.models).Count -eq 0) {
        Write-Host "  no ComfyUI roots found"
    }
    foreach ($model in @($Verify.models)) {
        Write-Host "  exists=$($model.exists) $($model.relativePath)"
        Write-Host "    $($model.path)"
    }
}

function Get-NextStepObject {
    param([string]$BaseRoot)

    $status = Get-StatusObject -BaseRoot $BaseRoot
    $torchPip = @($status.processes | Where-Object { $_.isTorchPip })
    $easyInstall = @($status.processes | Where-Object { $_.isEasyInstall })
    $listening = @($status.ports | Where-Object { $_.listening })

    $recommendation = $null
    $reason = $null
    $requiresConfirmation = $false

    if ($torchPip.Count -gt 0) {
        $recommendation = 'wait-current-torch-install'
        $reason = 'An embedded Python process is still installing torch. Do not start another install or mutate the same environment.'
    }
    elseif ($easyInstall.Count -gt 0) {
        $recommendation = 'continue-observing-current-easy-install'
        $reason = 'An Easy-Install related process is still active. Keep observing logs and ports.'
    }
    elseif (-not $status.paths.rootExists) {
        $recommendation = 'choose-root-before-staged-workflow'
        $reason = 'The configured root does not exist.'
        $requiresConfirmation = $true
    }
    elseif (@($status.paths.embeddedPythons).Count -eq 0 -or @($status.paths.comfyRoots).Count -eq 0) {
        $recommendation = 'verify-existing-root-and-installer-output'
        $reason = 'Root exists, but embedded Python or ComfyUI main.py was not found yet.'
    }
    elseif ($listening.Count -eq 0) {
        $recommendation = 'verify-existing-then-request-smoke-start-approval'
        $reason = 'Environment files exist, but no configured ComfyUI port is listening. Starting ComfyUI is a separate approval step.'
        $requiresConfirmation = $true
    }
    else {
        $recommendation = 'run-verify-existing-and-check-reactor-object-info'
        $reason = 'A configured port is listening, so API and ReActor object_info checks are the next read-only step.'
    }

    [pscustomobject]@{
        generatedAt = (Get-Date).ToString('s')
        mode = 'read-only'
        recommendation = $recommendation
        reason = $reason
        requiresConfirmation = $requiresConfirmation
        statusSummary = [pscustomobject]@{
            rootExists = $status.paths.rootExists
            processCount = @($status.processes).Count
            torchPipCount = $torchPip.Count
            easyInstallCount = $easyInstall.Count
            listeningPorts = @($listening | ForEach-Object { $_.port })
            comfyRootCount = @($status.paths.comfyRoots).Count
            embeddedPythonCount = @($status.paths.embeddedPythons).Count
        }
    }
}

function Write-NextStepHuman {
    param($Next)

    Write-Host "Next safe step: $($Next.recommendation)"
    Write-Host "Reason: $($Next.reason)"
    Write-Host "Requires confirmation: $($Next.requiresConfirmation)"
    Write-Host ""
    Write-Host "Snapshot:"
    Write-Host "  root exists: $($Next.statusSummary.rootExists)"
    Write-Host "  processes: $($Next.statusSummary.processCount)"
    Write-Host "  torch pip processes: $($Next.statusSummary.torchPipCount)"
    Write-Host "  easy-install processes: $($Next.statusSummary.easyInstallCount)"
    Write-Host "  listening ports: $(@($Next.statusSummary.listeningPorts) -join ', ')"
    Write-Host "  ComfyUI roots: $($Next.statusSummary.comfyRootCount)"
    Write-Host "  embedded Python: $($Next.statusSummary.embeddedPythonCount)"
}

switch ($Command) {
    'status' {
        $status = Get-StatusObject -BaseRoot $Root
        if ($Json) { $status | ConvertTo-Json -Depth 12 } else { Write-StatusHuman -Status $status }
    }
    'plan' {
        if (-not (Test-PathBool $PlanPath)) { throw "Plan file not found: $PlanPath" }
        $plan = Get-Content -LiteralPath $PlanPath -Raw | ConvertFrom-Json
        if ($Json) { $plan | ConvertTo-Json -Depth 12 } else { Write-PlanHuman -Plan $plan }
    }
    'verify-existing' {
        $verify = Get-VerifyObject -BaseRoot $Root
        if ($Json) { $verify | ConvertTo-Json -Depth 12 } else { Write-VerifyHuman -Verify $verify }
    }
    'next-step' {
        $next = Get-NextStepObject -BaseRoot $Root
        if ($Json) { $next | ConvertTo-Json -Depth 12 } else { Write-NextStepHuman -Next $next }
    }
}

