async function detectCropFromImage(imageUrl) {
  if (!("FaceDetector" in window)) return null;
  const detector = new FaceDetector({ fastMode: true, maxDetectedFaces: 1 });
  const image = new Image();
  image.decoding = "async";
  image.src = imageUrl;
  await image.decode();
  const faces = await detector.detect(image);
  const box = faces?.[0]?.boundingBox;
  if (!box || !image.naturalWidth || !image.naturalHeight) return null;
  const centerX = ((box.x + box.width / 2) / image.naturalWidth) * 100;
  const centerY = ((box.y + box.height * 0.22) / image.naturalHeight) * 100;
  const faceShare = box.height / image.naturalHeight;
  const zoom = Math.min(4.2, Math.max(1.7, 0.82 / faceShare));
  return { x: centerX, y: centerY, zoom, source: "browser" };
}

